configuration.tbelScript:
var telemetryMap = [
    'aa': 'device.runtime.active_alarms',
    'at': 'device.runtime.alarm_transition',
    'atemp': 'device.sensor.ambient_temp_c',
    'bat': 'electrical.battery_level_pct',
    'ct': 'network.radio.connection_type',
    'dlms_f': 'dlms.session.failed',
    'dlms_ok': 'dlms.session.completed',
    'dlms_r': 'dlms.read.retrying',
    'dlms_st': 'dlms.session.started',
    'err': 'device.runtime.error_code',
    'fw': 'device.firmware.version',
    'ha': 'device.health.alert_active',
    'hr': 'device.nic.hw_rev',
    'hsc': 'device.health.score',
    'iccid': 'device.nic.sim.iccid',
    'imei': 'device.nic.imei',
    'imsi': 'device.nic.sim.imsi',
    'kwh': 'electrical.energy_kwh',
    'lcy': 'network.radio.latency_ms',
    'ln': 'device.location.longitude',
    'loss': 'network.radio.packet_loss_pct',
    'lt': 'device.location.latitude',
    'main': 'electrical.mains_status',
    'nid': 'device.id.nic_id',
    'oper': 'device.nic.sim.operator',
    'ota_p': 'lifecycle.ota.progress_pct',
    'ota_st': 'lifecycle.ota.state',
    'pip': 'device.nic.sim.ip',
    'rsrp': 'network.radio.rsrp_dbm',
    'rsrq': 'network.radio.rsrq_db',
    'rssi': 'network.radio.rssi_dbm',
    'rx': 'network.stats.bytes_received',
    'sid': 'device.id.som_id',
    'sm': 'device.id.som_model',
    'snr': 'network.radio.snr_db',
    'temp': 'device.sensor.internal_temp_c',
    'tx': 'network.stats.bytes_sent',
    'uid': 'device.id.uid',
    'upt': 'device.runtime.uptime_s',
    'v': 'electrical.voltage_v'
];

var eventMap = [
    '1101': 'power.last_gasp.started',
    '1203': 'dlms.session.started',
    '1204': 'dlms.session.completed',
    '1804': 'device.boot'
];

var alarmMap = [
    '2101': 'power.mains.lost',
    '2103': 'power.battery.low',
    '2201': 'uart.meter.no_response'
];

var out = [:];
var partialFailures = [:];
var hasFailures = false;
var ignored = ['ev': true, 'schema': true, 'ts': true, 'deviceId': true, 'deviceName': true];

// 1. Telemetry - REMOVED 'var' FROM LOOP
for (key : msg.keySet()) {
    if (ignored[key] != true) {
        var canonical = telemetryMap[key];
        if (canonical != null) {
            out[canonical] = msg[key];
        } else {
            partialFailures[key] = msg[key];
            hasFailures = true;
        }
    }
}

// 2. Transitions
var transitions = msg.ev;
var mappedEvents = [];
var mappedAlarms = [];

if (transitions != null) {
    // REMOVED 'var' FROM LOOP
    for (t : transitions) {
        var code = '' + t.c;
        var stateCode = t.s;
        var lifecycleState = 'RAISED';
        if (stateCode == 0) { lifecycleState = 'CLEARED'; }
        if (stateCode == 2) { lifecycleState = 'UPDATED'; }

        var sourceEventTs = t.ts;
        if (sourceEventTs == null) { sourceEventTs = msg.ts; }
        if (sourceEventTs == null) { sourceEventTs = metadata.ts; }

        var eventCanonical = eventMap[code];

        if (eventCanonical != null) {
            var eventType = 'lifecycle';
            if (eventCanonical.startsWith('fota.') || eventCanonical.startsWith('ota.')) { 
                eventType = 'ota'; 
            }
            var evRow = [
                'candidateType': eventType,
                'canonicalEvent': eventCanonical,
                'sourceCode': code,
                'transitionState': lifecycleState,
                'sourceEventTs': sourceEventTs
            ];
            if (t.m != null) { evRow['metadata'] = t.m; }
            mappedEvents.add(evRow);
        } else {
            var alarmCanonical = alarmMap[code];
            if (alarmCanonical != null) {
                var alRow = [
                    'canonicalAlarm': alarmCanonical,
                    'sourceCode': code,
                    'state': stateCode,
                    'lifecycleState': lifecycleState,
                    'sourceEventTs': sourceEventTs
                ];
                if (t.m != null) { alRow['metadata'] = t.m; }
                mappedAlarms.add(alRow);
            }
        }
    }
}

// 3. Flags and Output
if (mappedEvents.size() > 0) {
    out['mappedEvents'] = mappedEvents;
    metadata.hasEvents = 'true';
}
if (mappedAlarms.size() > 0) {
    out['mappedAlarms'] = mappedAlarms;
    metadata.hasAlarms = 'true';
}

out['candidateType'] = 'device_state';

if (hasFailures) {
    out['partialFailures'] = partialFailures;
    return {msg: out, metadata: metadata, msgType: 'Failure'};
}

return {msg: out, metadata: metadata, msgType: msgType};

var routes = {
  'alarm': 'tb.nic.candidate.alarm.v1',
  'device_state': 'tb.nic.candidate.device-state.v1',
  'lifecycle': 'tb.nic.candidate.lifecycle.v1',
  'ota': 'tb.nic.candidate.ota.v1'
};
var candidateType = msg['candidateType'];
if (candidateType == null) {
  var err = {'error': 'missing_candidate_type', 'candidateType': 'dlt'};
  return {msg: err, metadata: metadata, msgType: 'Failure'};
}
var topic = routes[candidateType];
if (topic == null) {
  var err2 = {'error': 'unknown_candidate_type', 'value': candidateType, 'candidateType': 'dlt'};
  return {msg: err2, metadata: metadata, msgType: 'Failure'};
}
metadata['kafkaTopic'] = topic;
return {msg: msg, metadata: metadata, msgType: msgType};

