function nextRelation(metadata, msg) {
    return ['one','nine'];
}
if(msgType === 'POST_TELEMETRY_REQUEST') {
    return ['two'];
}
return nextRelation(metadata, msg);

configuration.tbelScript:
var s = msg.schema ;

// If schema is missing or not 1, route to Failure
if (s == null || ('' + s) != '1') {
    return ['Failure'];
}

// Otherwise, ensure it's in metadata and route to Success
metadata.schema = '' + s;
return ['Success'];
